INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(519825, 51629, 9941, '<td valign="top">Very nice and interesting photo.  Excellent DOF.</td>', 'Very nice and interesting photo.  Excellent DOF.', '2003-12-22 09:41:43.000000', NULL, 1),
(519826, 51511, 9941, '<td valign="top">Very unique and interesting.</td>', 'Very unique and interesting.', '2003-12-22 09:42:11.000000', NULL, 1),
(519828, 51752, 9939, '<td valign="top">Technical: fits the challenge. Exposure focus lighting all excellent- I absolutely love the saturation. Personally I feel the composition could have been stronger with a little more space above and below.<br/> <br/>Personal: The detail and color really make this shot for me.<br/> <br/>My vote: 8</td>', 'Technical: fits the challenge. Exposure focus lighting all excellent- I absolutely love the saturation. Personally I feel the composition could have been stronger with a little more space above and below. Personal: The detail and color really make this shot for me. My vote: 8', '2003-12-22 09:46:28.000000', NULL, 1),
(519829, 51211, 9941, '<td valign="top">Very nice! As a guitarist, I really enjoy looking at this type of photo.</td>', 'Very nice! As a guitarist, I really enjoy looking at this type of photo.', '2003-12-22 09:47:51.000000', NULL, 1),
