(520497, 51710, 15291, '<td valign="top">All around fantastic photograph....Love all the lines taking you in and out of the picture all of which take you to a different place in the photo. Clear crisp image with fine detail right down to the woods grain. Magnificant ! 10 !</td>', 'All around fantastic photograph....Love all the lines taking you in and out of the picture all of which take you to a different place in the photo. Clear crisp image with fine detail right down to the woods grain. Magnificant ! 10 !', '2003-12-22 22:49:30.000000', NULL, 1),
(520505, 51732, 12962, '<td valign="top">Very colorful.  At first glance, I thought they were Sufi dancers twirling taken from a bird''s eyeview.  Very nice!</td>', 'Very colorful.  At first glance, I thought they were Sufi dancers twirling taken from a bird''s eyeview.  Very nice!', '2003-12-22 23:09:42.000000', NULL, 1),
