(521011, 51758, 8286, '<td valign="top">I really like this shot.  Reminds me of Vertigo.</td>', 'I really like this shot.  Reminds me of Vertigo.', '2003-12-23 13:37:07.000000', NULL, 1),
(521012, 51701, 8624, '<td valign="top">one of the more nicely composed flower shots. good arrangement of the elements in the frame. the white and green looks terrific against the black background.</td>', 'one of the more nicely composed flower shots. good arrangement of the elements in the frame. the white and green looks terrific against the black background.', '2003-12-23 13:37:11.000000', NULL, 1),
(521015, 51693, 8286, '<td valign="top">I am not so sure about the framing on this, but it is very very well focused.</td>', 'I am not so sure about the framing on this, but it is very very well focused.', '2003-12-23 13:38:18.000000', NULL, 1),
(521016, 50991, 8624, '<td valign="top">great lighting and curves on the pepper. nice job.</td>', 'great lighting and curves on the pepper. nice job.', '2003-12-23 13:38:31.000000', NULL, 1),
(521017, 51740, 8286, '<td valign="top">Intense capture.  <br/>well done.</td>', 'Intense capture.  well done.', '2003-12-23 13:39:20.000000', NULL, 1),
(521018, 51366, 8624, '<td valign="top">I like the idea and composition. The shadow under the applicator is a bit harsh though.</td>', 'I like the idea and composition. The shadow under the applicator is a bit harsh though.', '2003-12-23 13:39:29.000000', NULL, 1),
(521019, 51622, 8286, '<td valign="top">This is one of those objects that you look at and can''t tell if it is a little thing, or large.  Hard to tell it''s a macro.</td>', 'This is one of those objects that you look at and can''t tell if it is a little thing, or large.  Hard to tell it''s a macro.', '2003-12-23 13:40:07.000000', NULL, 1),
(521020, 51827, 8286, '<td valign="top">I love the depth of field on this!!!!</td>', 'I love the depth of field on this!!!!', '2003-12-23 13:41:07.000000', NULL, 1),
(521022, 51128, 8286, '<td valign="top">Almost like crossed fingers.  I think I might have focused just on the two that are crossed.  Neat shot.</td>', 'Almost like crossed fingers.  I think I might have focused just on the two that are crossed.  Neat shot.', '2003-12-23 13:41:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(521023, 51181, 8286, '<td valign="top">Neat object.</td>', 'Neat object.', '2003-12-23 13:42:49.000000', NULL, 1),
(521024, 51360, 8286, '<td valign="top">Very very pretty, great saturation.</td>', 'Very very pretty, great saturation.', '2003-12-23 13:43:36.000000', NULL, 1),
(521025, 51744, 8624, '<td valign="top">I went back and forth on this over whether I liked the shadows or not. They add some visual interest but also clutter it up. Maybe if they had more contrast they could serve as additional interesting visual elements.</td>', 'I went back and forth on this over whether I liked the shadows or not. They add some visual interest but also clutter it up. Maybe if they had more contrast they could serve as additional interesting visual elements.', '2003-12-23 13:43:39.000000', NULL, 1),
(521026, 51171, 3087, '<td valign="top">Nice use of colour and DOF. I like the straight diagonal of the foreground and the way it contrasts with the lazy curves behind it.</td>', 'Nice use of colour and DOF. I like the straight diagonal of the foreground and the way it contrasts with the lazy curves behind it.', '2003-12-23 13:44:56.000000', NULL, 1),
(521027, 51498, 8286, '<td valign="top">This is so pretty.  I wish the flower were floating (to avoid the shadows at the bottom.  Nice tone and focus.</td>', 'This is so pretty.  I wish the flower were floating (to avoid the shadows at the bottom.  Nice tone and focus.', '2003-12-23 13:45:03.000000', NULL, 1),
(521028, 51706, 8286, '<td valign="top">In the thumbnail this looked like an animal.  Nicely done.</td>', 'In the thumbnail this looked like an animal.  Nicely done.', '2003-12-23 13:45:57.000000', NULL, 1),
(521029, 51827, 3087, '<td valign="top">An interesting use of perspective to transform an every day object into something more abstract.</td>', 'An interesting use of perspective to transform an every day object into something more abstract.', '2003-12-23 13:46:02.000000', NULL, 1),
(521030, 51428, 8286, '<td valign="top">Well done.</td>', 'Well done.', '2003-12-23 13:46:47.000000', NULL, 1),
(521031, 51698, 8624, '<td valign="top">nice interesting angle on the guitar. the highlights are overexposed though and the shadow on the peg is a bit harsh</td>', 'nice interesting angle on the guitar. the highlights are overexposed though and the shadow on the peg is a bit harsh', '2003-12-23 13:46:57.000000', NULL, 1),
(521032, 51734, 3087, '<td valign="top">I love the colours reflected in the glass - particularly on the ridges formed by the raised lettering.</td>', 'I love the colours reflected in the glass - particularly on the ridges formed by the raised lettering.', '2003-12-23 13:47:09.000000', NULL, 1),
(521033, 51719, 8286, '<td valign="top">beautiful</td>', 'beautiful', '2003-12-23 13:47:23.000000', NULL, 1),
(521034, 51167, 8624, '<td valign="top">would have been a great shot if it was sharper. interesting textures in the denim and brass are lost in the fuzziness.</td>', 'would have been a great shot if it was sharper. interesting textures in the denim and brass are lost in the fuzziness.', '2003-12-23 13:47:57.000000', NULL, 1),
(521035, 51752, 3087, '<td valign="top">The lighting transforms the petals into flames for me. Very dramatic. The choice of black background helps emphasise the colours in the flower and stem.</td>', 'The lighting transforms the petals into flames for me. Very dramatic. The choice of black background helps emphasise the colours in the flower and stem.', '2003-12-23 13:48:19.000000', NULL, 1),
(521036, 51710, 10858, '<td valign="top">Amazing metal photograph, lighting is excellent! You have given a great soft feeling to the steely clockwork, and the purple stuff gives a nice warm element to the photo, too. I wouldn''t change a thing, take 10 and good luck! :-)</td>', 'Amazing metal photograph, lighting is excellent! You have given a great soft feeling to the steely clockwork, and the purple stuff gives a nice warm element to the photo, too. I wouldn''t change a thing, take 10 and good luck! :-)', '2003-12-23 13:49:31.000000', NULL, 1),
(521037, 51629, 8286, '<td valign="top">Lovely.  I wish her wings were a bit more focused.</td>', 'Lovely.  I wish her wings were a bit more focused.', '2003-12-23 13:49:50.000000', NULL, 1),
(521038, 50909, 3087, '<td valign="top">A striking portrait. Composition is strengthened by being brave enough to crop tight. The crop means that, for me, the whiskers lead me into the photograph rather than out of it and my focus stays with those mesmerising eyes.</td>', 'A striking portrait. Composition is strengthened by being brave enough to crop tight. The crop means that, for me, the whiskers lead me into the photograph rather than out of it and my focus stays with those mesmerising eyes.', '2003-12-23 13:49:59.000000', NULL, 1),
(521039, 51760, 8624, '<td valign="top">I like the off center framing. I think it would have been more interesting had the center of the flower been at a slight angle rather than strait on.</td>', 'I like the off center framing. I think it would have been more interesting had the center of the flower been at a slight angle rather than strait on.', '2003-12-23 13:50:31.000000', NULL, 1),
(521040, 51557, 8286, '<td valign="top">Neat shot but the lighting is a little distracting.  It may have been more effective with the light on the snakes head.</td>', 'Neat shot but the lighting is a little distracting.  It may have been more effective with the light on the snakes head.', '2003-12-23 13:50:50.000000', NULL, 1),
(521041, 51541, 3087, '<td valign="top">This has a really different feel to many other entries and I can this kind of studio shot appearing in magazine adverts etc. Good use of DOF and a nice simple arrangement and perspective.</td>', 'This has a really different feel to many other entries and I can this kind of studio shot appearing in magazine adverts etc. Good use of DOF and a nice simple arrangement and perspective.', '2003-12-23 13:51:03.000000', NULL, 1),
(521042, 51167, 8286, '<td valign="top">A bit blurry.</td>', 'A bit blurry.', '2003-12-23 13:51:06.000000', NULL, 1),
(521043, 51580, 3087, '<td valign="top">Interesting framing!</td>', 'Interesting framing!', '2003-12-23 13:51:27.000000', NULL, 1),
(521044, 51350, 8286, '<td valign="top">Wow...neat.  He looks like an old man.</td>', 'Wow...neat.  He looks like an old man.', '2003-12-23 13:52:03.000000', NULL, 1),
(521046, 51644, 10858, '<td valign="top">Great idea and composition, I also like the angle. All I could mention against is that II would have chosen a background with a colour that has more contrast with the bud and there is a white speckle (5 cm from the left, 2 cm from the top) which could be removed easily.</td>', 'Great idea and composition, I also like the angle. All I could mention against is that II would have chosen a background with a colour that has more contrast with the bud and there is a white speckle (5 cm from the left, 2 cm from the top) which could be removed easily.', '2003-12-23 13:52:45.000000', NULL, 1),
(521047, 51514, 8286, '<td valign="top">Odd shot.  The color/black and white makes this uncomfortable to look at.</td>', 'Odd shot.  The color/black and white makes this uncomfortable to look at.', '2003-12-23 13:52:53.000000', NULL, 1),
(521048, 51148, 8624, '<td valign="top">extra points for a creative effort on your composition.</td>', 'extra points for a creative effort on your composition.', '2003-12-23 13:52:54.000000', NULL, 1),
(521049, 51167, 3087, '<td valign="top">And it all unravels? Great shot though too much shadow at top left corner for my preferences.</td>', 'And it all unravels? Great shot though too much shadow at top left corner for my preferences.', '2003-12-23 13:52:56.000000', NULL, 1),
(521051, 51790, 8286, '<td valign="top">Interesting shot.  The reflection is a little distracting.</td>', 'Interesting shot.  The reflection is a little distracting.', '2003-12-23 13:54:22.000000', NULL, 1),
(521052, 51332, 3087, '<td valign="top">This one certainly made me look, look and look again. I like the slightly surreal edge it has - both content wise and compositionally.</td>', 'This one certainly made me look, look and look again. I like the slightly surreal edge it has - both content wise and compositionally.', '2003-12-23 13:54:29.000000', NULL, 1),
(521053, 51770, 8624, '<td valign="top">nice lighting and good sharp image. the composition is too cluttered for my taste, but it is a nice capture.</td>', 'nice lighting and good sharp image. the composition is too cluttered for my taste, but it is a nice capture.', '2003-12-23 13:54:30.000000', NULL, 1),
(521054, 51593, 10858, '<td valign="top">I am not sure this would be a macro, rather a close-up. If I were you, I wouldn''t have cropped the cat''s left ear and the paw. I like the colours, the tounge gives a nice colour element to the photo. :-)</td>', 'I am not sure this would be a macro, rather a close-up. If I were you, I wouldn''t have cropped the cat''s left ear and the paw. I like the colours, the tounge gives a nice colour element to the photo. :-)', '2003-12-23 13:55:13.000000', NULL, 1),
(521055, 51508, 3087, '<td valign="top">Nice restricted colour palette, simple but strong composition.</td>', 'Nice restricted colour palette, simple but strong composition.', '2003-12-23 13:55:17.000000', NULL, 1),
(521056, 51721, 8286, '<td valign="top">EEEEK!  Close enough for discomfort.  Excellent shot.</td>', 'EEEEK!  Close enough for discomfort.  Excellent shot.', '2003-12-23 13:55:26.000000', NULL, 1),
(521057, 51726, 3087, '<td valign="top">Beautiful rich tones very well captured.</td>', 'Beautiful rich tones very well captured.', '2003-12-23 13:55:46.000000', NULL, 1),
(521058, 51683, 8286, '<td valign="top">Interesting concept.  The reflection is distracting.</td>', 'Interesting concept.  The reflection is distracting.', '2003-12-23 13:57:07.000000', NULL, 1),
(521059, 51385, 3087, '<td valign="top">I love this! What a great macro! I love the way I can see the fibrous textures of the thread itself. I also really like the uneven vertical lines and the three blocks of similar colours. A great macro and a great image!</td>', 'I love this! What a great macro! I love the way I can see the fibrous textures of the thread itself. I also really like the uneven vertical lines and the three blocks of similar colours. A great macro and a great image!', '2003-12-23 13:57:33.000000', NULL, 1),
(521060, 51800, 8624, '<td valign="top">a very interesting view of a common object. well done! my personal favorite in this competition</td>', 'a very interesting view of a common object. well done! my personal favorite in this competition', '2003-12-23 13:57:37.000000', NULL, 1),
(521061, 51806, 3087, '<td valign="top">Wow! Beautifully captured!</td>', 'Wow! Beautifully captured!', '2003-12-23 13:57:57.000000', NULL, 1),
(521064, 51691, 12448, '<td valign="top">Very interesting, I like the idea and the way the fruit is lighted up from behind but for some reason I''m thinking this could be just a tad sharper, not completely sharp but just a tad.  And the heavy black border really detracts from the overall shot.  A 7</td>', 'Very interesting, I like the idea and the way the fruit is lighted up from behind but for some reason I''m thinking this could be just a tad sharper, not completely sharp but just a tad.  And the heavy black border really detracts from the overall shot.  A 7', '2003-12-23 14:02:01.000000', NULL, 1),
(521065, 51701, 12448, '<td valign="top">How pretty and the DOF is very well done, I like the cropping, the composure of the shot and the black background works very well with this shot.  A 10!</td>', 'How pretty and the DOF is very well done, I like the cropping, the composure of the shot and the black background works very well with this shot.  A 10!', '2003-12-23 14:02:54.000000', NULL, 1),
(521066, 51511, 10705, '<td valign="top">Very interesting shot ... love the detail!</td>', 'Very interesting shot ... love the detail!', '2003-12-23 14:03:33.000000', NULL, 1),
(521068, 51332, 12448, '<td valign="top">Oh, I like this idea!  Very unique and different!  The title fits very well but the handle are distracating.  I would love to see this with a tighter crop and the blades at the same angle.  A 9</td>', 'Oh, I like this idea!  Very unique and different!  The title fits very well but the handle are distracating.  I would love to see this with a tighter crop and the blades at the same angle.  A 9', '2003-12-23 14:04:19.000000', NULL, 1),
(521069, 51209, 10705, '<td valign="top">Very nice shot of an everyday item!</td>', 'Very nice shot of an everyday item!', '2003-12-23 14:04:25.000000', NULL, 1),
(521070, 51161, 10858, '<td valign="top">Rather a close up, I don''t know. I would have gone a bit closer if your camera allows you closer shots. Your main subject could be a bit sharper, background a bit less busy (or more blurry). My outtake was a Christmas ornament, too, I know it''s hard but it''s worth to try. :-)</td>', 'Rather a close up, I don''t know. I would have gone a bit closer if your camera allows you closer shots. Your main subject could be a bit sharper, background a bit less busy (or more blurry). My outtake was a Christmas ornament, too, I know it''s hard but it''s worth to try. :-)', '2003-12-23 14:04:32.000000', NULL, 1),
(521072, 51817, 10705, '<td valign="top">red lights at the bottom are a little distracting, but nice job!</td>', 'red lights at the bottom are a little distracting, but nice job!', '2003-12-23 14:07:16.000000', NULL, 1),
(521073, 51678, 10858, '<td valign="top">I guess it''s a stalk of an apple. :-) Great composition, maybe the shadow could have been got out - with lighting or PhotoShop.</td>', 'I guess it''s a stalk of an apple. :-) Great composition, maybe the shadow could have been got out - with lighting or PhotoShop.', '2003-12-23 14:07:37.000000', NULL, 1),
(521074, 51338, 10705, '<td valign="top">excellent clarity</td>', 'excellent clarity', '2003-12-23 14:08:21.000000', NULL, 1),
(521078, 51438, 10858, '<td valign="top">Hm, I don''t know how big or small this vase is in real life, I am in trouble. :-) I like the roustic texture and the colours against the dark white wall.</td>', 'Hm, I don''t know how big or small this vase is in real life, I am in trouble. :-) I like the roustic texture and the colours against the dark white wall.', '2003-12-23 14:11:20.000000', NULL, 1),
(521085, 51687, 15324, '<td valign="top">Nice colours. I like the simplicity.</td>', 'Nice colours. I like the simplicity.', '2003-12-23 14:22:34.000000', NULL, 1),
(521086, 51019, 10705, '<td valign="top">WOW  ... incredible detail, colors, clarity ... this photo has it all!!!</td>', 'WOW  ... incredible detail, colors, clarity ... this photo has it all!!!', '2003-12-23 14:23:04.000000', NULL, 1),
(521087, 51752, 10705, '<td valign="top">Nice composition, detail and color!</td>', 'Nice composition, detail and color!', '2003-12-23 14:27:16.000000', NULL, 1),
(521088, 51714, 10705, '<td valign="top">very creative ... I like it!!!</td>', 'very creative ... I like it!!!', '2003-12-23 14:29:33.000000', NULL, 1),
(521115, 51824, 10809, '<td valign="top">very nice. Maybe it''s be even nicer of there were more of the yellow leaves in the photo. but still looks great.</td>', 'very nice. Maybe it''s be even nicer of there were more of the yellow leaves in the photo. but still looks great.', '2003-12-23 14:57:46.000000', NULL, 1),
(521117, 51541, 10809, '<td valign="top">nice picture but not sure if it''ll count as a macro.</td>', 'nice picture but not sure if it''ll count as a macro.', '2003-12-23 15:10:32.000000', NULL, 1),
(521118, 51727, 6597, '<td valign="top">The red thread has a good effect in this photo. Being on that sews or used to<br/>I can see that you have captured the small details on the sewing machine &amp;</td>', 'The red thread has a good effect in this photo. Being on that sews or used toI can see that you have captured the small details on the sewing machine &', '2003-12-23 15:11:05.000000', NULL, 1),
(521119, 51593, 10809, '<td valign="top">cool cat. But not a marco</td>', 'cool cat. But not a marco', '2003-12-23 15:13:38.000000', NULL, 1),
(521120, 51799, 10809, '<td valign="top">This HAS to be the best photo in this challenge. You have got to win. The composition and colours are magnificeint. Beautiful.</td>', 'This HAS to be the best photo in this challenge. You have got to win. The composition and colours are magnificeint. Beautiful.', '2003-12-23 15:18:01.000000', NULL, 1),
(521137, 51122, 9448, '<td valign="top">Nice composition.  Good focus.  Nice DOF.  Nice lighting.  I like the colourisation, nice editing.  Excellent contrast too.  Well done.Good luck.</td>', 'Nice composition.  Good focus.  Nice DOF.  Nice lighting.  I like the colourisation, nice editing.  Excellent contrast too.  Well done.Good luck.', '2003-12-23 15:51:29.000000', NULL, 1),
(521139, 51791, 9448, '<td valign="top">Very nice idea, shame that it is not really a macro.  Also your picture could really do with being straightened up, try rotating it about a degree anticlockwise.<br/>Nice and different, good colours.  Good luck.</td>', 'Very nice idea, shame that it is not really a macro.  Also your picture could really do with being straightened up, try rotating it about a degree anticlockwise.Nice and different, good colours.  Good luck.', '2003-12-23 15:55:41.000000', NULL, 1),
(521140, 51828, 10809, '<td valign="top">How did you get hold of this? :)<br/>Cool photo</td>', 'How did you get hold of this? :)Cool photo', '2003-12-23 15:55:56.000000', NULL, 1),
(521142, 51744, 9448, '<td valign="top">Nice composition.  Good focus.  Good use of lighting.  Well done.Good luck.</td>', 'Nice composition.  Good focus.  Good use of lighting.  Well done.Good luck.', '2003-12-23 15:56:48.000000', NULL, 1),
(521147, 51604, 9448, '<td valign="top">Interesting shot, I''ve wanted to do one like this for a while -- but I could never think up a good subject.<br/> <br/>I''m not convinced by the shade of blue that you''ve used, and I also think that you could have used more of the main subjects in focus.  Good focus and good depth of field.  Good composition apart from like I mentioned before that I would have preferred to see more of the in focus subject.</td>', 'Interesting shot, I''ve wanted to do one like this for a while -- but I could never think up a good subject. I''m not convinced by the shade of blue that you''ve used, and I also think that you could have used more of the main subjects in focus.  Good focus and good depth of field.  Good composition apart from like I mentioned before that I would have preferred to see more of the in focus subject.', '2003-12-23 16:01:56.000000', NULL, 1),
(521153, 51128, 9448, '<td valign="top">Very good, good capture of detail and nice focus.  I would have preferred to see slightly more depth of field so that both the main branch and the branch on the very left are in focus all the way up to the top where they meet.  Good black background -- shame about the noise in it.<br/> <br/>I recommend that you run the picture through Neatimage, and then mask the background and use Neatimage only on the background in this picture.  This way you will retain full detail in the flower, but remove the noise from the background.<br/> <br/>Good picture, nice execution good luck in the challenge.</td>', 'Very good, good capture of detail and nice focus.  I would have preferred to see slightly more depth of field so that both the main branch and the branch on the very left are in focus all the way up to the top where they meet.  Good black background -- shame about the noise in it. I recommend that you run the picture through Neatimage, and then mask the background and use Neatimage only on the background in this picture.  This way you will retain full detail in the flower, but remove the noise from the background. Good picture, nice execution good luck in the challenge.', '2003-12-23 16:06:07.000000', NULL, 1),
(521160, 51662, 9448, '<td valign="top">Nice gradiented background, good detail and crisp focus.  My favourite so far in this challenge.</td>', 'Nice gradiented background, good detail and crisp focus.  My favourite so far in this challenge.', '2003-12-23 16:19:50.000000', NULL, 1),
(521184, 51794, 3087, '<td valign="top">I really really like this very much indeed. Your choice of subject matter is excellent - it has wonderful texture, colour, form... and your composition and DOF choice serve to emphasise all those aspects very well. A striking image.</td>', 'I really really like this very much indeed. Your choice of subject matter is excellent - it has wonderful texture, colour, form... and your composition and DOF choice serve to emphasise all those aspects very well. A striking image.', '2003-12-23 16:59:37.000000', NULL, 1),
(521191, 51753, 3087, '<td valign="top">I think the composition is very strong here, the tight curves of the ball seams complement the lazier curves of the yellow glove. I think lighting makes the final image look a little flat though - somehow lacking in vibrancy, if that makes sense.</td>', 'I think the composition is very strong here, the tight curves of the ball seams complement the lazier curves of the yellow glove. I think lighting makes the final image look a little flat though - somehow lacking in vibrancy, if that makes sense.', '2003-12-23 17:06:27.000000', NULL, 1),
(521193, 51691, 3087, '<td valign="top">Wow! It''s like looking at a Monet - the texture is wonderful - makes it all more abstract. The colours are so vibrant. And of course  the composition is excellent - the square crop and cornered design work so well. Love it!</td>', 'Wow! It''s like looking at a Monet - the texture is wonderful - makes it all more abstract. The colours are so vibrant. And of course  the composition is excellent - the square crop and cornered design work so well. Love it!', '2003-12-23 17:08:41.000000', NULL, 1),
(521195, 51360, 3087, '<td valign="top">Simplicity is king. This is exceptionally well done. The balance of background and the two foreground elements is just perfect as is the balance of colours and the angle of the bauble. The composition created by the angle and the exact crop - how much bauble is included, how close the ring is to the edges of the frame - is just excellent. One of my favourite entries in the challenge.</td>', 'Simplicity is king. This is exceptionally well done. The balance of background and the two foreground elements is just perfect as is the balance of colours and the angle of the bauble. The composition created by the angle and the exact crop - how much bauble is included, how close the ring is to the edges of the frame - is just excellent. One of my favourite entries in the challenge.', '2003-12-23 17:10:49.000000', NULL, 1),
(521196, 51771, 3087, '<td valign="top">Interesting use of DOF to really bring our focus to one area of the image. Good capture of textures that one might not normally notice. I like the tight crop and angled composition too.</td>', 'Interesting use of DOF to really bring our focus to one area of the image. Good capture of textures that one might not normally notice. I like the tight crop and angled composition too.', '2003-12-23 17:11:56.000000', NULL, 1),
(521199, 51582, 3087, '<td valign="top">The harsh lighting and choice of black and white work very well to emphasise the nature of the subject matter. An intriguing image that makes me ask questions about the owner as well as provoking more abstract thoughts about work/ vocation.</td>', 'The harsh lighting and choice of black and white work very well to emphasise the nature of the subject matter. An intriguing image that makes me ask questions about the owner as well as provoking more abstract thoughts about work/ vocation.', '2003-12-23 17:13:10.000000', NULL, 1),
(521201, 51781, 3087, '<td valign="top">An interesting subject - great texture and form. I wonder if a portrait orientation would have suited this image better. Lighting seems quite flat also.</td>', 'An interesting subject - great texture and form. I wonder if a portrait orientation would have suited this image better. Lighting seems quite flat also.', '2003-12-23 17:14:17.000000', NULL, 1),
(521202, 51334, 3087, '<td valign="top">The lighting and colour conveys quite an interesting sense of mood - like watching a strange sci-fi film or documentary on life in the deep deep deep oceans... I like it!</td>', 'The lighting and colour conveys quite an interesting sense of mood - like watching a strange sci-fi film or documentary on life in the deep deep deep oceans... I like it!', '2003-12-23 17:16:45.000000', NULL, 1),
(521203, 51122, 3087, '<td valign="top">This is a really nice coin macro. I often find them a tad boring or uninspired but I really like this image (and it''s not just because I am more familiar with the currency!). The clarity is superb, the DOF gives focus on a nice amount of detail and the composition within the frame, with just two corners of black background showing, works well.</td>', 'This is a really nice coin macro. I often find them a tad boring or uninspired but I really like this image (and it''s not just because I am more familiar with the currency!). The clarity is superb, the DOF gives focus on a nice amount of detail and the composition within the frame, with just two corners of black background showing, works well.', '2003-12-23 17:18:16.000000', NULL, 1),
(521204, 51662, 3087, '<td valign="top">This is beautiful, very light and ethereal.</td>', 'This is beautiful, very light and ethereal.', '2003-12-23 17:19:07.000000', NULL, 1),
(521205, 51614, 3087, '<td valign="top">Being a fan of limited DOF, when used to add interest, this shot does intrigue me. Colour contrast is certainly very seasonal!</td>', 'Being a fan of limited DOF, when used to add interest, this shot does intrigue me. Colour contrast is certainly very seasonal!', '2003-12-23 17:19:57.000000', NULL, 1),
(521206, 51629, 3087, '<td valign="top">Absolutely beautiful. The cool blues of the butterfly show wonderfully against the warmer pinks and oranges of the flowers. The green background is very subtle indeed. Your limited DOF works just perfectly in blurring it out. I think this is a really strong image.</td>', 'Absolutely beautiful. The cool blues of the butterfly show wonderfully against the warmer pinks and oranges of the flowers. The green background is very subtle indeed. Your limited DOF works just perfectly in blurring it out. I think this is a really strong image.', '2003-12-23 17:22:35.000000', NULL, 1),
(521207, 51019, 3087, '<td valign="top">Wow! You can see the individual pollen on his back! Nicely captured!</td>', 'Wow! You can see the individual pollen on his back! Nicely captured!', '2003-12-23 17:23:37.000000', NULL, 1),
(521209, 51678, 3087, '<td valign="top">An apple? What a clever approach - to go in so close to one small part of a familiar object that we see the shapes and texture in a new way. I like this very much.</td>', 'An apple? What a clever approach - to go in so close to one small part of a familiar object that we see the shapes and texture in a new way. I like this very much.', '2003-12-23 17:26:41.000000', NULL, 1),
(521210, 51825, 3087, '<td valign="top">I like the choice of black background and the dark lighting does give mood but I''d like to see the lady bird (that''s what we call them in the UK, incase you''re about to tell me it''s a lady bug) in more detail. Composition works well for me.</td>', 'I like the choice of black background and the dark lighting does give mood but I''d like to see the lady bird (that''s what we call them in the UK, incase you''re about to tell me it''s a lady bug) in more detail. Composition works well for me.', '2003-12-23 17:28:01.000000', NULL, 1),
(521211, 51758, 3087, '<td valign="top">Oooh I wonder what I did with my old metronome? I really like the unusual viewpoint in this - it makes a really strong diagonal of the moving thingy.</td>', 'Oooh I wonder what I did with my old metronome? I really like the unusual viewpoint in this - it makes a really strong diagonal of the moving thingy.', '2003-12-23 17:30:09.000000', NULL, 1),
(521212, 51648, 3087, '<td valign="top">Simple, nice lighting, nice use of shadow.</td>', 'Simple, nice lighting, nice use of shadow.', '2003-12-23 17:30:51.000000', NULL, 1),
(521213, 51819, 3087, '<td valign="top">A wonderful texture and I like the focal point of the silver opening. I feel composition would be stronger if the silver circle were further into the frame rather than touching the edge.</td>', 'A wonderful texture and I like the focal point of the silver opening. I feel composition would be stronger if the silver circle were further into the frame rather than touching the edge.', '2003-12-23 17:34:22.000000', NULL, 1),
(521214, 51720, 3087, '<td valign="top">Good choice of background to bring out the red in the leaf. Nice use of the diagonal vein lines and leaf edge to strengthen composition.</td>', 'Good choice of background to bring out the red in the leaf. Nice use of the diagonal vein lines and leaf edge to strengthen composition.', '2003-12-23 17:35:19.000000', NULL, 1),
(521215, 51706, 3087, '<td valign="top">I love the drama of your spotlight approach. Certainly adds impact.</td>', 'I love the drama of your spotlight approach. Certainly adds impact.', '2003-12-23 17:36:06.000000', NULL, 1),
(521216, 51800, 3087, '<td valign="top">Beautiful study of two contrasting textures and the red against the beige and brown of the ball surface works very well. Composition is also strong with the off-centred diagonal line curving up to the corner of the frame. Lighting seems a little weak to the right.</td>', 'Beautiful study of two contrasting textures and the red against the beige and brown of the ball surface works very well. Composition is also strong with the off-centred diagonal line curving up to the corner of the frame. Lighting seems a little weak to the right.', '2003-12-23 17:37:42.000000', NULL, 1),
(521217, 51721, 3087, '<td valign="top">Ow! The cactus spikes certainly add interest and drama though one has to feel sorry for the little critter. Nice shot!</td>', 'Ow! The cactus spikes certainly add interest and drama though one has to feel sorry for the little critter. Nice shot!', '2003-12-23 17:38:44.000000', NULL, 1),
(521218, 51465, 3087, '<td valign="top">Mmm - so many contrasts. Warm colour of the chain but cold metal. Soft fluffy appearance of the snow but actually cold wetness. I like the simplicity of composition and background.</td>', 'Mmm - so many contrasts. Warm colour of the chain but cold metal. Soft fluffy appearance of the snow but actually cold wetness. I like the simplicity of composition and background.', '2003-12-23 17:40:26.000000', NULL, 1),
(521220, 51687, 3087, '<td valign="top">Wow! This is a strong impact image. Great composition with the pencil lead tip positioned to point to one corner angled from the opposite one. Choice of background colour is spot on. Light and textures look great.</td>', 'Wow! This is a strong impact image. Great composition with the pencil lead tip positioned to point to one corner angled from the opposite one. Choice of background colour is spot on. Light and textures look great.', '2003-12-23 17:42:25.000000', NULL, 1),
(521228, 51800, 14936, '<td valign="top">Awesome detail!!!  I love it!</td>', 'Awesome detail!!!  I love it!', '2003-12-23 17:57:22.000000', NULL, 1),
