(524027, 51800, 7304, '<td valign="top">Well done macro. Love the feel of the baseball and threads. Exposure is right on. 8</td>', 'Well done macro. Love the feel of the baseball and threads. Exposure is right on. 8', '2003-12-27 19:22:20.000000', NULL, 1),
(524030, 51734, 7304, '<td valign="top">The colors are great. Nice and sharp. This is agreat shot and very interesting. 7</td>', 'The colors are great. Nice and sharp. This is agreat shot and very interesting. 7', '2003-12-27 19:23:28.000000', NULL, 1),
