(524335, 51726, 2553, '<td valign="top">Though not a visually or emotionally high impact shot for me, the composition is interesting, nice focus throughout, and nice warm color with good tonal range.</td>', 'Though not a visually or emotionally high impact shot for me, the composition is interesting, nice focus throughout, and nice warm color with good tonal range.', '2003-12-28 07:28:05.000000', NULL, 1),
(524336, 51465, 2553, '<td valign="top">Subject is crisp and clear, and dof is good, however photo seems pretty dark, and I would like to have seen a more dynamic composition.</td>', 'Subject is crisp and clear, and dof is good, however photo seems pretty dark, and I would like to have seen a more dynamic composition.', '2003-12-28 07:29:32.000000', NULL, 1),
(524337, 51687, 3306, '<td valign="top">Simple but very effective. Excellent Macro.</td>', 'Simple but very effective. Excellent Macro.', '2003-12-28 07:32:02.000000', NULL, 1),
(524338, 51761, 2553, '<td valign="top">Edges seem either overexposed or oversharpened.  Good focus on the prickly things, and good color.  The composition just doesn''t "draw me in".</td>', 'Edges seem either overexposed or oversharpened.  Good focus on the prickly things, and good color.  The composition just doesn''t "draw me in".', '2003-12-28 07:33:18.000000', NULL, 1),
(524339, 51370, 3306, '<td valign="top">This is a really interesting picture even though the colors of the cloth are bright, it is the models green eye that lures my attention.</td>', 'This is a really interesting picture even though the colors of the cloth are bright, it is the models green eye that lures my attention.', '2003-12-28 07:33:55.000000', NULL, 1),
(524343, 51019, 12802, '<td valign="top">Brilliant photo here, really like the subject!...<br/> <br/>The background colours, and the colour of the flower go well, these details add those few extra points for me. The only thing I would have liked to see was this a little sharper.  <br/> <br/>Well done! 10</td>', 'Brilliant photo here, really like the subject!... The background colours, and the colour of the flower go well, these details add those few extra points for me. The only thing I would have liked to see was this a little sharper.   Well done! 10', '2003-12-28 07:43:20.000000', NULL, 1),
(524344, 50909, 2553, '<td valign="top">Actually a very nice shot; good dof and lighting, but not high impact for me, and not *just because it''s a cat*.  I like cats a lot, and don''t mind shots of cats, but this is what I would think of as a fairly "common" type of cat shot.  There is nothing unusual;  nothing to really hold my interest; doesn''t have an unexpected or dynamic composition that would really make it stand out.  None of this is said to be mean, or to hurt your feelings, but merely to say that when shooting something like this, it would be the something "unexpected" that would really make someone stop and say "hey, this is cool".</td>', 'Actually a very nice shot; good dof and lighting, but not high impact for me, and not *just because it''s a cat*.  I like cats a lot, and don''t mind shots of cats, but this is what I would think of as a fairly "common" type of cat shot.  There is nothing unusual;  nothing to really hold my interest; doesn''t have an unexpected or dynamic composition that would really make it stand out.  None of this is said to be mean, or to hurt your feelings, but merely to say that when shooting something like this, it would be the something "unexpected" that would really make someone stop and say "hey, this is cool".', '2003-12-28 07:44:18.000000', NULL, 1),
(524346, 51582, 2553, '<td valign="top">Different.  Nice lighting, composition and dof.  Love the black and white treatment-has good tonal range that makes it interesting.  Not high impact in a "WOW" kind of way, but definitely has visual interest.</td>', 'Different.  Nice lighting, composition and dof.  Love the black and white treatment-has good tonal range that makes it interesting.  Not high impact in a "WOW" kind of way, but definitely has visual interest.', '2003-12-28 07:46:34.000000', NULL, 1),
(524367, 51393, 6624, '<td valign="top">when I was a kid there used to be a story about the star in the apple...nice capture with a few light spots that detract</td>', 'when I was a kid there used to be a story about the star in the apple...nice capture with a few light spots that detract', '2003-12-28 10:11:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(524368, 51513, 6624, '<td valign="top">the textures and shapes are very good - the whitish spot just left of the bottom bud is a bit of a distraction but otherwise a fine image</td>', 'the textures and shapes are very good - the whitish spot just left of the bottom bud is a bit of a distraction but otherwise a fine image', '2003-12-28 10:12:33.000000', NULL, 1),
(524369, 51769, 6624, '<td valign="top">this image makes me hungry every time I look at it - I hope you have included a recipe...nice macro</td>', 'this image makes me hungry every time I look at it - I hope you have included a recipe...nice macro', '2003-12-28 10:13:25.000000', NULL, 1),
(524370, 51299, 6624, '<td valign="top">the concept is very nice, it is a bit too dark, however, and your idea seems lost in the shadows</td>', 'the concept is very nice, it is a bit too dark, however, and your idea seems lost in the shadows', '2003-12-28 10:14:40.000000', NULL, 1),
(524371, 51691, 6624, '<td valign="top">this feels over-processed to me and the black border detracts a lot</td>', 'this feels over-processed to me and the black border detracts a lot', '2003-12-28 10:16:45.000000', NULL, 1),
(524372, 51662, 6624, '<td valign="top">nice composition and color, good clarity, has a feel of embossed notepaper though - not quite a wow</td>', 'nice composition and color, good clarity, has a feel of embossed notepaper though - not quite a wow', '2003-12-28 10:19:36.000000', NULL, 1),
(524373, 51710, 6624, '<td valign="top">very nice composition, soft focus works well, colors warm and appealing - a nice capture</td>', 'very nice composition, soft focus works well, colors warm and appealing - a nice capture', '2003-12-28 10:20:33.000000', NULL, 1),
(524374, 51663, 6624, '<td valign="top">a lovely little orchid, good clarity and colors, focus clear and composition straightforward and simple</td>', 'a lovely little orchid, good clarity and colors, focus clear and composition straightforward and simple', '2003-12-28 10:21:48.000000', NULL, 1),
(524375, 51465, 6624, '<td valign="top">textures and colors clear -- composition and even the shadow of the chain links lack "wow"</td>', 'textures and colors clear -- composition and even the shadow of the chain links lack "wow"', '2003-12-28 10:23:09.000000', NULL, 1),
(524376, 51717, 6624, '<td valign="top">almost a flower - too harsh a light though</td>', 'almost a flower - too harsh a light though', '2003-12-28 10:23:54.000000', NULL, 1),
(524377, 51519, 6624, '<td valign="top">good composition and clarity, nice texture on the cone, fun title</td>', 'good composition and clarity, nice texture on the cone, fun title', '2003-12-28 10:24:36.000000', NULL, 1),
(524387, 51498, 3569, '<td valign="top">Nice backlighting effect</td>', 'Nice backlighting effect', '2003-12-28 11:04:55.000000', NULL, 1),
(524388, 51658, 3569, '<td valign="top">Interesting idea, but focus appears off to me.</td>', 'Interesting idea, but focus appears off to me.', '2003-12-28 11:06:59.000000', NULL, 1),
(524390, 51752, 3569, '<td valign="top">great sharpness and contrasts very nice.</td>', 'great sharpness and contrasts very nice.', '2003-12-28 11:09:00.000000', NULL, 1),
(524391, 51649, 3569, '<td valign="top">a darker background would have helped.</td>', 'a darker background would have helped.', '2003-12-28 11:09:37.000000', NULL, 1),
(524444, 51000, 10858, '<td valign="top">Lighting is harsh on the left and could be more in focus. The idea is good, it''s just hard to make good photos of metal.</td>', 'Lighting is harsh on the left and could be more in focus. The idea is good, it''s just hard to make good photos of metal.', '2003-12-28 15:08:28.000000', NULL, 1),
(524447, 51498, 10858, '<td valign="top">I like this shot, but I think I would like to see all the petals, I wouldn''t have cropped them.</td>', 'I like this shot, but I think I would like to see all the petals, I wouldn''t have cropped them.', '2003-12-28 15:13:32.000000', NULL, 1),
(524448, 51691, 9448, '<td valign="top">I had the idea of doing shot like this, and have been wanting to do one for a while.  It was ashamed that I did not have a Kiwi fruits of the last day of the challenge which is when I took my picture.<br/> <br/>I like your composition, and the way that the outer parts of the Kiwi fruit and the seeds take a ride towards the middle.  Personally I would have run the picture through Neatimage in order to get rid of some of the noise, and I would have used a slightly small border.<br/> <br/>Overall a good shot, good luck in the challenge.</td>', 'I had the idea of doing shot like this, and have been wanting to do one for a while.  It was ashamed that I did not have a Kiwi fruits of the last day of the challenge which is when I took my picture. I like your composition, and the way that the outer parts of the Kiwi fruit and the seeds take a ride towards the middle.  Personally I would have run the picture through Neatimage in order to get rid of some of the noise, and I would have used a slightly small border. Overall a good shot, good luck in the challenge.', '2003-12-28 15:13:51.000000', NULL, 1),
(524450, 51817, 10858, '<td valign="top">Red light blow outs on the bottom are a bit distracting, I would have cropped them. I like the colours and the DOF here, the Christmas lights are good, too, no blow-outs with them. :-)</td>', 'Red light blow outs on the bottom are a bit distracting, I would have cropped them. I like the colours and the DOF here, the Christmas lights are good, too, no blow-outs with them. :-)', '2003-12-28 15:15:38.000000', NULL, 1),
(524453, 51793, 9448, '<td valign="top">Interesting picture, very shallow depth of field and almost a complete lack of noise.  I also like a way that the border draws your eye towards the dark parts of the image, therefore providing greater contrast to the blue in the image.<br/> <br/>I personally think that the depth of field should either have be used to concentrat on just one particular part of the image, or that you should have used a greater depth of field to show off the shape that you have in this particular picture.  The shape is not really borne out by the fact that it is a bit blurred.<br/>Also by using a very shallow depth of field, but not concentrating on just one particular element, you have ended up with a picture where you effectively have three parts in focus which are on a diagonal from bottom left to top right.  This leaves the opposing diagonal somewhat empty and devoid of focus.  Maybe it is this that seems to unbalanced this particular image.<br/> <br/>As it stands there is something that I don''t quite like about the image, but it is very good nonetheless.  You have also achieved very crisp focus, which is obviously a benefit in a macro.  Good luck.</td>', 'Interesting picture, very shallow depth of field and almost a complete lack of noise.  I also like a way that the border draws your eye towards the dark parts of the image, therefore providing greater contrast to the blue in the image. I personally think that the depth of field should either have be used to concentrat on just one particular part of the image, or that you should have used a greater depth of field to show off the shape that you have in this particular picture.  The shape is not really borne out by the fact that it is a bit blurred.Also by using a very shallow depth of field, but not concentrating on just one particular element, you have ended up with a picture where you effectively have three parts in focus which are on a diagonal from bottom left to top right.  This leaves the opposing diagonal somewhat empty and devoid of focus.  Maybe it is this that seems to unbalanced this particular image. As it stands there is something that I don''t quite like about the image, but it is very good nonetheless.  You have also achieved very crisp focus, which is obviously a benefit in a macro.  Good luck.', '2003-12-28 15:22:22.000000', NULL, 1),
(524454, 51607, 10858, '<td valign="top">One of my favourite flowers, I love African Violets soo much! :-) Nice composition, maybe the petals in the background could be a bit more in focus.</td>', 'One of my favourite flowers, I love African Violets soo much! :-) Nice composition, maybe the petals in the background could be a bit more in focus.', '2003-12-28 15:23:40.000000', NULL, 1),
(524455, 51758, 10858, '<td valign="top">Wow, I know what this is! :-) I have learnt piano for 4 years and I used this stuff so much. I like the diagonal composition and sepia tones here a much! :-)</td>', 'Wow, I know what this is! :-) I have learnt piano for 4 years and I used this stuff so much. I like the diagonal composition and sepia tones here a much! :-)', '2003-12-28 15:25:29.000000', NULL, 1),
(524456, 51367, 10858, '<td valign="top">Wow, the 3rd African Violet I have seen in this challenge. :-) I love them! This one has wonderful colours, I just would have composed the yellows following the rules of thirds. I like your DOF.</td>', 'Wow, the 3rd African Violet I have seen in this challenge. :-) I love them! This one has wonderful colours, I just would have composed the yellows following the rules of thirds. I like your DOF.', '2003-12-28 15:27:46.000000', NULL, 1),
(524457, 51513, 10858, '<td valign="top">African violet? Love this flower! I have one in the bathroom and it blossoms in every year (twice) since 1999. :-) A bit greany as for the background, but alltogether a cool photo! I like the hair of the flower being visible, wonderful. :-)</td>', 'African violet? Love this flower! I have one in the bathroom and it blossoms in every year (twice) since 1999. :-) A bit greany as for the background, but alltogether a cool photo! I like the hair of the flower being visible, wonderful. :-)', '2003-12-28 15:28:22.000000', NULL, 1),
(524458, 51799, 527, '<td valign="top">Well this has to be one of the top five, if not the outright winner. This is just beautiful with excellent composition, colors and textures. Even the slight noise adds something to it for me. -10<br/> <br/>T</td>', 'Well this has to be one of the top five, if not the outright winner. This is just beautiful with excellent composition, colors and textures. Even the slight noise adds something to it for me. -10 T', '2003-12-28 15:35:01.000000', NULL, 1),
(524460, 51621, 527, '<td valign="top">I can tell that there is beauty in here but I feel it would have worked much better if you would have cropped a lot tighter on one of the elements to isolate it from all of the distracting elements. It''s just too busy as it is.   5<br/> <br/>T</td>', 'I can tell that there is beauty in here but I feel it would have worked much better if you would have cropped a lot tighter on one of the elements to isolate it from all of the distracting elements. It''s just too busy as it is.   5 T', '2003-12-28 15:44:46.000000', NULL, 1),
(524470, 50991, 527, '<td valign="top">Nice abstract. Beautiful lighting, values and composition. The black and white adds a nice element of mystery and mood. -9<br/> <br/>T</td>', 'Nice abstract. Beautiful lighting, values and composition. The black and white adds a nice element of mystery and mood. -9 T', '2003-12-28 15:48:30.000000', NULL, 1),
(524473, 51541, 527, '<td valign="top">This is excellent. Clean and simple with nice comosition, subtle colors and details. The use of a shallow DOF really makes the photo.  -10<br/> <br/>T</td>', 'This is excellent. Clean and simple with nice comosition, subtle colors and details. The use of a shallow DOF really makes the photo.  -10 T', '2003-12-28 15:51:40.000000', NULL, 1),
(524481, 51511, 527, '<td valign="top">This is very nice. A very good composition with a bold horizontal line that helps solidify the image while all the small details create a fun and interesting image. Duotone helps put the focus on the composition and individual elements.  -9<br/> <br/>T</td>', 'This is very nice. A very good composition with a bold horizontal line that helps solidify the image while all the small details create a fun and interesting image. Duotone helps put the focus on the composition and individual elements.  -9 T', '2003-12-28 16:10:19.000000', NULL, 1),
(524484, 51752, 527, '<td valign="top">This is very beautiful. Everything is excellent except I am not comfortable with the tip of the pedal nearly touching the border. It creates a visual tension that distracts from the rest of the image. Excellent color and textures.  -9<br/> <br/>T</td>', 'This is very beautiful. Everything is excellent except I am not comfortable with the tip of the pedal nearly touching the border. It creates a visual tension that distracts from the rest of the image. Excellent color and textures.  -9 T', '2003-12-28 16:14:43.000000', NULL, 1),
(524485, 51387, 10858, '<td valign="top">He is cute! :-) I like the composition, colours and the texture of background. I guess the title is his name, not the score you await, because this is a 9 here! :-)</td>', 'He is cute! :-) I like the composition, colours and the texture of background. I guess the title is his name, not the score you await, because this is a 9 here! :-)', '2003-12-28 16:14:57.000000', NULL, 1),
(524495, 51691, 3936, '<td valign="top">I''m not a big border fan.  This is a border that works.  I like everything about this picture, the focus the lighting, the exposure.  The kiwi seems to glow with a light of it''s own.  I would love to have a stained glass window just like this.  This is art!<br/>10!</td>', 'I''m not a big border fan.  This is a border that works.  I like everything about this picture, the focus the lighting, the exposure.  The kiwi seems to glow with a light of it''s own.  I would love to have a stained glass window just like this.  This is art!10!', '2003-12-28 16:43:57.000000', NULL, 1),
(524558, 51108, 10402, '<td valign="top">The harsh lighting makes the venation really stand out, but to me the strong contrast it creates isn''t consistent with the character of the leaf.</td>', 'The harsh lighting makes the venation really stand out, but to me the strong contrast it creates isn''t consistent with the character of the leaf.', '2003-12-28 17:38:59.000000', NULL, 1),
(524569, 51128, 10402, '<td valign="top">Interesting shapes and nice contrasting background. Depth of field is a bit narrow; it would be better if the main stems were better focused (although the out of focus foreground works great). And a closer shot would have been more appropriate for a Macro challenge.</td>', 'Interesting shapes and nice contrasting background. Depth of field is a bit narrow; it would be better if the main stems were better focused (although the out of focus foreground works great). And a closer shot would have been more appropriate for a Macro challenge.', '2003-12-28 17:46:56.000000', NULL, 1),
(524586, 51793, 10402, '<td valign="top">The center and corners being the only things in focus gives this a rather funky appearance. Maybe it would work if there was some space around the in-focus bracts at top and bottom, but I don''t find it very interesting as it is.</td>', 'The center and corners being the only things in focus gives this a rather funky appearance. Maybe it would work if there was some space around the in-focus bracts at top and bottom, but I don''t find it very interesting as it is.', '2003-12-28 17:56:23.000000', NULL, 1),
(524587, 51439, 10402, '<td valign="top">The backlit string at the right attracts too much attention, even though it is near the edge and out of focus. Removing it and increasing the depth of field so the entire shell is in focus rather than just the top part would make this photo a lot more interesting.</td>', 'The backlit string at the right attracts too much attention, even though it is near the edge and out of focus. Removing it and increasing the depth of field so the entire shell is in focus rather than just the top part would make this photo a lot more interesting.', '2003-12-28 18:00:30.000000', NULL, 1),
(524628, 50973, 12160, '<td valign="top">great focus on the froggy, shallow dof works, overall nice photo.</td>', 'great focus on the froggy, shallow dof works, overall nice photo.', '2003-12-28 19:15:41.000000', NULL, 1),
(524659, 51822, 14509, '<td valign="top">Great idea. Well focused.</td>', 'Great idea. Well focused.', '2003-12-28 20:17:08.000000', NULL, 1),
(524660, 51740, 14509, '<td valign="top">I can''t vote, but this would be chosen as first place by me. Well done.</td>', 'I can''t vote, but this would be chosen as first place by me. Well done.', '2003-12-28 20:17:49.000000', NULL, 1),
